def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    def opp_run(val):
        k = 0
        for a in reversed(opp):
            if a == val:
                k += 1
            else:
                break
        return k

    def my_run(val):
        k = 0
        for a in reversed(me):
            if a == val:
                k += 1
            else:
                break
        return k

    total_opp_c = opp.count('C')
    total_opp_d = n - total_opp_c
    recent_len = min(10, n)
    recent = opp[-recent_len:]
    recent_c = recent.count('C')
    recent_d = recent_len - recent_c
    last5 = opp[-5:]
    last5_c = last5.count('C')

    # Opening: cooperate briefly, but be ready to retaliate quickly.
    if n <= 2:
        return 'C'

    # If opponent is in a long defect streak, stay in defect mode.
    if last_opp == 'D':
        dstreak = opp_run('D')
        if dstreak >= 3:
            return 'D'
        # If opponent defects after mostly cooperating, retaliate but don't overcommit.
        if total_opp_c * 5 >= n * 4:
            return 'D'
        if recent_c >= 6 and dstreak == 1:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent cooperated last.
    cstreak = opp_run('C')
    # If opponent has been almost perfectly cooperative, exploit moderately late.
    if total_opp_c >= n - 1:
        if n >= 85:
            return 'D'
        if n >= 30 and n % 14 == 0:
            return 'D'
        return 'C'

    # If opponent has an occasional defection pattern, punish when fresh.
    if last5_c >= 4 and total_opp_d > 0:
        if n >= 78:
            return 'D'
        if recent_d >= 1 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # If opponent is mostly defecting overall, be aggressive.
    if total_opp_d * 2 >= n:
        if last5_c <= 2:
            return 'D'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # If we just defected and opponent still cooperated, occasional continued exploit.
    if last_me == 'D':
        if n >= 88:
            return 'D'
        if my_run('D') == 1 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Mostly cooperative opponent, mostly cooperate, with rare probes.
    if cstreak >= 3:
        if n >= 92:
            return 'D'
        if n >= 40 and n % 11 == 0:
            return 'D'
        return 'C'

    if recent_c >= 8:
        if n >= 18 and n % 9 == 0:
            return 'D'
        return 'C'

    if last_opp == 'C':
        return 'C'

    return 'C'
